export function getEmployeeExperience(scenarioId: string): EmployeeExperience {
  const candidate = EMPLOYEE_EXPERIENCES[scenarioId as EmployeeScenarioId];
  return candidate ?? EMPLOYEE_EXPERIENCES['my-day'];
}

export const ALL_EMPLOYEE_EXPERIENCES: ReadonlyArray<EmployeeExperience> = EMPLOYEE_SCENARIO_IDS.map((scenarioId) => EMPLOYEE_EXPERIENCES[scenarioId]);
